SELECT id, message_id, session_id, ticket_id, sender_type, sender_id, content, created_at_ms
FROM cw_chat_message
WHERE session_id = #{sessionId}

    AND id < #{beforeId}

ORDER BY id DESC
LIMIT #{limit}

SELECT id, message_id, session_id, ticket_id, sender_type, sender_id, content, created_at_ms
FROM cw_chat_message
WHERE ticket_id = #{ticketId}

    AND id < #{beforeId}

ORDER BY id DESC
LIMIT #{limit}
